const docs = [
  { source: 'Standard: Tagging', text: 'All AWS resources MUST carry the tags Owner, Env, and CostCenter. Plans that create resources without these tags violate policy and should be flagged as needs_changes.' },
  { source: 'Standard: Encryption at rest', text: 'All data stores must have encryption at rest enabled: S3 buckets (SSE), RDS instances, and EBS volumes. A new S3 bucket or RDS instance without encryption is a policy violation.' },
  { source: 'Standard: No public exposure', text: 'S3 buckets must never be public (no public-read/public-write ACLs or public bucket policies). Security group ingress from 0.0.0.0/0 is prohibited except 443 on public load balancers. SSH (port 22) must NEVER be open to 0.0.0.0/0. Treat public exposure as high/critical risk and block.' },
  { source: 'Standard: Destructive changes', text: 'Replace or delete of stateful resources (RDS, DynamoDB, S3, EBS) is high risk. RDS instances must have deletion_protection=true and must NOT set skip_final_snapshot=true. BLOCK any plan that replaces or deletes an RDS instance without a final snapshot - this is data-loss risk. Destructive changes to stateful resources require human approval before apply.' },
  { source: 'Standard: Naming conventions', text: 'Resource names follow <env>-<service>-<resource>, e.g. prod-web-alb. Flag names that do not match the convention.' },
  { source: 'Standard: Cost guardrails', text: 'Prefer Graviton (t4g/m7g) instance types where possible. Flag new or resized instances larger than xlarge and any plan that materially increases monthly cost for review.' },
  { source: 'Standard: Least privilege IAM', text: 'IAM policies must not use wildcard actions or resources (Action: * or Resource: *). Flag any new IAM policy or role that grants wildcard permissions.' },
  { source: 'Standard: Apply / approval process', text: 'approve = safe, standards-compliant, non-destructive changes. needs_changes = policy or tagging violations that are not data-loss or public-exposure. block = data-loss risk (destructive stateful change without safeguards) or public exposure. Applies to stateful or security-group changes always require human sign-off.' }
];
return docs.map((d) => ({ json: { text: d.text, source: d.source }, pairedItem: { item: 0 } }));
